 private Map<String,Object> validatePixels()throws Exception{
  var a=javax.imageio.ImageIO.read(images.resolve("lens-zero-control-a.png").toFile());var b=javax.imageio.ImageIO.read(images.resolve("lens-zero-control-b.png").toFile());var lens=javax.imageio.ImageIO.read(images.resolve("lens-refraction-full.png").toFile());var blur=javax.imageio.ImageIO.read(images.resolve("lens-blur-full.png").toFile());double meanA=0,meanBlur=0,edgeA=0,edgeBlur=0,noise=0,refraction=0;int count=0;
  for(int y=110;y<a.getHeight()-160;y++)for(int x=120;x<a.getWidth()-120;x++){int aa=a.getRGB(x,y),bb=b.getRGB(x,y),ll=lens.getRGB(x,y),ss=blur.getRGB(x,y);for(int shift:new int[]{0,8,16}){int av=aa>>shift&255,bv=bb>>shift&255,lv=ll>>shift&255,sv=ss>>shift&255;meanA+=av;meanBlur+=sv;noise+=Math.abs(av-bv);refraction+=Math.abs(av-lv);edgeA+=Math.abs(av-(a.getRGB(x-4,y)>>shift&255));edgeBlur+=Math.abs(sv-(blur.getRGB(x-4,y)>>shift&255));count++;}}
  double luminanceRatio=meanBlur/meanA,edgeRatio=edgeBlur/edgeA;
  if(luminanceRatio<.75||luminanceRatio>1.25||edgeRatio>.85)throw new AssertionError("Blur pixels are not a luminance-preserving low-pass result: luminance="+luminanceRatio+" edge="+edgeRatio);
  if(refraction<noise*3+count*.1)throw new AssertionError("Refraction does not exceed unchanged-scene pixel noise");return Map.of("blurLuminanceRatio",luminanceRatio,"blurEdgeEnergyRatio",edgeRatio,"refractionMeanAbsoluteRgbDifference",refraction/count,"controlNoiseMeanAbsoluteRgbDifference",noise/count);
 }
 private void hoverRegression(ClientGameTestContext c)throws Exception{
  c.runOnClient(mc->{var core=VotexClient.INSTANCE;Path theme=core.directory.resolve("hover-regression-theme.json");Files.writeString(theme,"{\"schemaVersion\":1,\"accent\":\"#ad70ff\",\"secondary\":\"#ad70ff\",\"proximityEffect\":true,\"proximity\":100,\"reflection\":100,\"reflectionEffect\":true}");core.theme=ThemeConfig.read(theme);core.modules.config().glass=new GlassConfig();mc.gui.setScreen(new GlassHoverProbeScreen());});c.waitTicks(15);shot(c,"hover-mask-base");
  c.runOnClient(mc->((GlassHoverProbeScreen)mc.gui.screen()).lighting=true);c.waitTicks(3);shot(c,"hover-mask-left");
  c.runOnClient(mc->{var screen=(GlassHoverProbeScreen)mc.gui.screen();screen.pointerX=256;});c.waitTicks(1);shot(c,"hover-mask-right-immediate");
  var base=javax.imageio.ImageIO.read(images.resolve("hover-mask-base.png").toFile());var left=javax.imageio.ImageIO.read(images.resolve("hover-mask-left.png").toFile());var right=javax.imageio.ImageIO.read(images.resolve("hover-mask-right-immediate.png").toFile());int cornerMax=0;
  for(int[] corner:new int[][]{{101,71},{277,71},{101,115},{277,115}})for(int y=corner[1]*2;y<corner[1]*2+3;y++)for(int x=corner[0]*2;x<corner[0]*2+3;x++)for(int shift:new int[]{0,8,16})cornerMax=Math.max(cornerMax,Math.abs((base.getRGB(x,y)>>shift&255)-(right.getRGB(x,y)>>shift&255)));
  double ll=hoverEnergy(left,base,124,94),lr=hoverEnergy(left,base,256,94),rl=hoverEnergy(right,base,124,94),rr=hoverEnergy(right,base,256,94);
  if(cornerMax>2||ll<lr+2||rr<rl+2)throw new AssertionError("Rounded/direct hover regression: corner="+cornerMax+" left="+ll+","+lr+" right="+rl+","+rr);
  if(((Number)c.computeOnClient(mc->VotexGlassEngine.metrics()).get("actualLightDraws")).longValue()==0)throw new AssertionError("Interaction pipeline never executed");
  proof.put("roundedHoverPixelChecks",Map.of("outsideCornerMaxChannelDifference",cornerMax,"leftSpotLeftEnergy",ll,"leftSpotRightEnergy",lr,"rightSpotLeftEnergy",rl,"rightSpotRightEnergy",rr,"cursorMoveWaitTicks",1));
  c.runOnClient(mc->mc.gui.setScreen(new VotexScreen(VotexClient.INSTANCE,"MODULES")));c.waitTicks(15);c.getInput().setCursorPos(145,345);c.waitTicks(8);shot(c,"modules-purple-rounded-hover");
  c.runOnClient(mc->mc.gui.setScreen(new ModLibraryScreen(VotexClient.INSTANCE,new VotexScreen(VotexClient.INSTANCE,"MODULES"))));c.waitTicks(30);c.getInput().setCursorPos(280,268);c.waitTicks(8);shot(c,"mod-library-purple-hover");c.getInput().setCursorPos(0,0);
  c.runOnClient(mc->{VotexClient.INSTANCE.theme=ThemeConfig.defaults();mc.gui.setScreen(null);});
 }
 private void menuRegression(ClientGameTestContext c)throws Exception{
  var screen=c.computeOnClient(mc->(VotexScreen)mc.gui.screen());var opened=VotexScreen.class.getDeclaredField("opened");opened.setAccessible(true);long originalOpened=opened.getLong(screen);var method=VotexScreen.class.getDeclaredMethod("sampleMotion");method.setAccessible(true);var scaleField=VotexScreen.class.getDeclaredField("uiScale");scaleField.setAccessible(true);var bounds=new int[4];String[] fields={"left","top","w","panelHeight"};for(int i=0;i<4;i++){var f=VotexScreen.class.getDeclaredField(fields[i]);f.setAccessible(true);bounds[i]=f.getInt(screen);}
  for(String label:new String[]{"Garderobe","Skins","Emotes","Einstellungen","Mod Menu"}){
   c.runOnClient(mc->{try{var button=(GlassButton)screen.children().stream().filter(v->v instanceof GlassButton b&&b.getMessage().getString().equals(label)).findFirst().orElseThrow();var frame=(dev.votex.ui.WorkspaceMotion.Frame)method.invoke(screen);double scale=scaleField.getFloat(screen);var event=new net.minecraft.client.input.MouseButtonEvent(frame.screenX(button.getX()+button.getWidth()/2.)*scale,frame.screenY(button.getY()+button.getHeight()/2.)*scale,new net.minecraft.client.input.MouseButtonInfo(0,0));screen.mouseClicked(event,false);screen.mouseReleased(event);if(mc.gui.screen()!=screen||opened.getLong(screen)!=originalOpened)throw new AssertionError("Category restarted whole screen");var now=(dev.votex.ui.WorkspaceMotion.Frame)method.invoke(screen);if(Math.abs(now.scale()-1)>.0001||Math.abs(now.x())>.0001||Math.abs(now.y())>.0001)throw new AssertionError("Category transformed the outer window: "+now);for(int i=0;i<4;i++){var f=VotexScreen.class.getDeclaredField(fields[i]);f.setAccessible(true);if(f.getInt(screen)!=bounds[i])throw new AssertionError("Category moved/resized container");}}catch(ReflectiveOperationException e){throw new AssertionError(e);}});c.waitTicks(1);shot(c,"stable-category-"+label.toLowerCase(Locale.ROOT));c.waitTicks(5);
  }
  proof.put("categorySwitchKeepsScreenWindowAndOpeningClock",true);
 }
