  c.runOnClient(mc->{var slider=(GlassSlider)mc.gui.screen().children().stream().filter(v->v instanceof GlassSlider).skip(1).findFirst().orElseThrow();slider.mouseDragged(new net.minecraft.client.input.MouseButtonEvent(slider.getX()+slider.getWidth()-18,slider.getY()+32,new net.minecraft.client.input.MouseButtonInfo(0,0)),slider.getWidth()-36,0);if(VotexClient.INSTANCE.modules.config().glass.blur!=100)throw new AssertionError("Slider right endpoint imprecise");});c.waitTicks(1);shot(c,"slider-drag-right");
  c.runOnClient(mc->{var slider=(GlassSlider)mc.gui.screen().children().stream().filter(v->v instanceof GlassSlider).skip(1).findFirst().orElseThrow();slider.mouseDragged(new net.minecraft.client.input.MouseButtonEvent(slider.getX()+18,slider.getY()+32,new net.minecraft.client.input.MouseButtonInfo(0,0)),-slider.getWidth()+36,0);});c.waitTicks(1);shot(c,"slider-direction-reversal");
  c.runOnClient(mc->{var slider=(GlassSlider)mc.gui.screen().children().stream().filter(v->v instanceof GlassSlider).skip(1).findFirst().orElseThrow();slider.onRelease(new net.minecraft.client.input.MouseButtonEvent(slider.getX()+18,slider.getY()+32,new net.minecraft.client.input.MouseButtonInfo(0,0)));});c.waitTicks(30);shot(c,"slider-released-settled");proof.put("sliderExactEndpointsAndDragReversal",true);
