 private static double hoverEnergy(java.awt.image.BufferedImage image,java.awt.image.BufferedImage base,int cx,int cy){double sum=0;int count=0;for(int y=cy*2-10;y<cy*2+10;y++)for(int x=cx*2-10;x<cx*2+10;x++)for(int shift:new int[]{0,8,16}){sum+=Math.abs((image.getRGB(x,y)>>shift&255)-(base.getRGB(x,y)>>shift&255));count++;}return sum/count;}
 private void shot(ClientGameTestContext c,String name){c.takeScreenshot(TestScreenshotOptions.of(name).withDestinationDir(images).disableCounterPrefix());}
 private void backdrop(ClientGameTestContext c,String name){
  var server=c.computeOnClient(mc->mc.getSingleplayerServer());var id=c.computeOnClient(mc->mc.player.getUUID());
  var result=server.submit(()->{var p=server.getPlayerList().getPlayer(id);var level=server.getLevel(name.equals("nether")?Level.NETHER:Level.OVERWORLD);var white=name.equals("snow")?Blocks.SNOW_BLOCK:name.equals("water")?Blocks.PRISMARINE:name.equals("nether")?Blocks.NETHERRACK:Blocks.DEEPSLATE;var black=name.equals("nether")?Blocks.SHROOMLIGHT:Blocks.OBSIDIAN;
   for(int x=-12;x<=12;x++)for(int z=-3;z<=11;z++){level.setBlock(new BlockPos(x,99,z),Blocks.STONE.defaultBlockState(),3);for(int y=100;y<=111;y++){boolean edge=x==-12||x==12||z==-3||z==11;var block=z==10?((x/2+y/2)%2==0?white:black):(name.equals("water")?(edge||y==111?Blocks.GLASS:Blocks.WATER):(name.equals("cave")&&(edge||y==111)?Blocks.DEEPSLATE:Blocks.AIR));level.setBlock(new BlockPos(x,y,z),block.defaultBlockState(),3);}}
   p.teleportTo(level,.5,100,0.,Set.of(),0,0,false);return true;});c.waitFor(mc->result.isDone(),1000);result.join();c.waitTicks(20);c.runOnClient(mc->{mc.options.setCameraType(CameraType.FIRST_PERSON);mc.player.setXRot(0);mc.player.setYRot(0);});
 }
